import React, { useCallback, useContext, useEffect, useState } from 'react';
import { useIntl } from 'react-intl';

import { WrapTextIcon, WrapTextOffIcon } from '@dynatrace/strato-icons';

import { Button } from '../../buttons/button/Button.js';
import { Tooltip } from '../../overlays/tooltip/Tooltip.js';
import { DataTableContext } from '../contexts/DataTableContext.js';
import { dataTableMessages } from '../DataTable/messages.js';
import { useUserActionsActions } from '../plugins/use-user-actions/actions.js';

/**
 * DataTable toolbar button for toggling the line wrapping of the data table.
 *
 * @returns LineWrap component
 */
export const LineWrap = () => {
  const tableContext = useContext(DataTableContext);
  const {
    allColumns,
    visibleColumns,
    lineWrap: defaultTableLineWrap,
    dispatch,
  } = tableContext;

  const intl = useIntl();

  const [tableLineWrap, setTableLineWrap] = useState(defaultTableLineWrap);

  const lineWrapLabel = tableLineWrap
    ? intl.formatMessage(dataTableMessages.disableLineWrapLabel)
    : intl.formatMessage(dataTableMessages.enableLineWrapLabel);

  const shouldUpdateLineWrap = useCallback(() => {
    return visibleColumns?.length
      ? visibleColumns?.every((col) => (col ? col.lineWrap !== false : true))
      : false;
  }, [visibleColumns]);

  const onColumnLineWrapChange = useCallback(() => {
    setTableLineWrap(shouldUpdateLineWrap());
  }, [shouldUpdateLineWrap]);

  /**
   * This will usually only run when the component gets mounted.It updates the `lineWrap`
   * property of all columns so that they are all defined.
   */
  useEffect(() => {
    allColumns?.forEach(
      (col) => (col.lineWrap = col.lineWrap ?? defaultTableLineWrap),
    );
  }, [allColumns, defaultTableLineWrap]);

  /**
   * The component needs to know when a column toggles its `lineWrap` using a user action, so it
   * can update the icon.
   */
  useEffect(() => {
    tableContext.onColumnLineWrapChange = onColumnLineWrapChange;
  }, [tableContext, onColumnLineWrapChange]);

  /**
   * Updates the icon in the toolbar if a column gets removed/added or its visibility gets toggled.
   */
  useEffect(() => {
    setTableLineWrap(shouldUpdateLineWrap());
  }, [shouldUpdateLineWrap]);

  return (
    <Tooltip text={lineWrapLabel}>
      <Button
        aria-label={lineWrapLabel}
        onClick={() => {
          const newLineWrap = !tableLineWrap;

          allColumns?.forEach((col) => (col.lineWrap = newLineWrap));
          setTableLineWrap(newLineWrap);
          dispatch({
            type: useUserActionsActions.columnPropertiesChanged,
          });
        }}
      >
        <Button.Prefix>
          {tableLineWrap ? <WrapTextIcon /> : <WrapTextOffIcon />}
        </Button.Prefix>
      </Button>
    </Tooltip>
  );
};

LineWrap.displayName = 'DataTable.LineWrap';
